fieldProjection.command:
node --input-type=module -e 'import fs from "node:fs";import crypto from "node:crypto";import assert from "node:assert/strict";
const base="docs/reviews/browser-peer-scale-assurance/";
const read=p=>fs.readFileSync(base+p,"utf8");const json=p=>JSON.parse(read(p));
const questions=json("browser-scale-questions.json").questions;const ids=questions.map(q=>q.id);const rule=json("browser-scale-comparison-rule.json");assert.deepEqual(rule.questionIds,ids);
const keys=["k84","s17"].map(id=>({id,key:json("readings/"+id+"/browser-scale-judge-key.json"),reading:read("readings/"+id+"/browser-scale-reading.txt")}));
assert.deepEqual(keys[0].key.scoring,keys[1].key.scoring);assert.deepEqual(keys[0].key.rules,keys[1].key.rules);
const fields=keys.map(({id,key,reading})=>{
 assert.deepEqual(key.entries.map(e=>e.id),ids);
 const judgeInstructions=JSON.stringify({scoring:key.scoring,rules:key.rules},null,2);
 const properties=questions.map(q=>{const entry=key.entries.find(e=>e.id===q.id);assert.deepEqual(Object.keys(entry).sort(),["grounding","id","required","wrong"]);const prop={id:q.id,type:"comprehension",decidedBy:"judge",question:q.prompt,answerHeading:q.id,key:JSON.stringify(entry,null,2),scale:[0,2],judgedWith:["delivered"]};assert.deepEqual(JSON.parse(prop.key),entry);return prop});
 assert.deepEqual(JSON.parse(judgeInstructions),{scoring:key.scoring,rules:key.rules});
 const instructions=read("browser-scale-reader-instructions.md");
 const task=questions.map(q=>q.id+"\n"+q.prompt).join("\n\n");
 const payloadBytes=Buffer.byteLength(reading)+Buffer.byteLength(instructions)+Buffer.byteLength(task);
 assert.ok(payloadBytes<=65536);
 return {id,readerInstructionsBytes:Buffer.byteLength(instructions),questionTaskBytes:Buffer.byteLength(task),readingBytes:Buffer.byteLength(reading),payloadBytes,commonJudgeInstructionsBytes:Buffer.byteLength(judgeInstructions),propertyProjection:properties.map((p,i)=>({question:p.id,fields:Object.keys(p),keyBytes:Buffer.byteLength(p.key),entryExact:true,required:key.entries[i].required.length,wrong:key.entries[i].wrong.length,grounding:key.entries[i].grounding.length})),instructions,task,judgeInstructions,properties};
});
assert.equal(fields[0].instructions,fields[1].instructions);assert.equal(fields[0].task,fields[1].task);assert.equal(fields[0].judgeInstructions,fields[1].judgeInstructions);
const families=["f1","f2","f3"];const cells=keys.flatMap(({id})=>families.map(family=>({reading:id,family})));const outcomes=cells.flatMap(cell=>ids.map(question=>({...cell,question})));const slots=outcomes.flatMap(o=>families.filter(f=>f!==o.family).map(judgeFamily=>({...o,judgeFamily})));assert.equal(cells.length,6);assert.equal(outcomes.length,48);assert.equal(slots.length,96);assert.equal(new Set(slots.map(s=>JSON.stringify(s))).size,96);
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
const sources=["docs/reviews/browser-peer-scale-assurance/browser-scale-assurance-preparation.md","docs/reviews/browser-peer-scale-assurance/browser-scale-reader-instructions.md","docs/reviews/browser-peer-scale-assurance/browser-scale-questions.json","docs/reviews/browser-peer-scale-assurance/browser-scale-comparison-rule.json","docs/reviews/browser-peer-scale-assurance/browser-scale-input-manifest.json","docs/reviews/browser-peer-scale-assurance/readings/k84/browser-scale-judge-key.json","docs/reviews/browser-peer-scale-assurance/readings/s17/browser-scale-judge-key.json","docs/reviews/browser-peer-scale-assurance/readings/k84/browser-scale-reading.txt","docs/reviews/browser-peer-scale-assurance/readings/s17/browser-scale-reading.txt","/home/apnex/taceng/context-lab/docs/OPERATIONS.md","/home/apnex/taceng/context-lab/incoming/agp-assurance-compatibility-review-response.md","/home/apnex/taceng/mission-kit/components/C2-context-lab.md"].map(path=>{const b=fs.readFileSync(path);return{path,bytes:b.length,sha256:sha(b)}});
console.log(JSON.stringify({result:"PASS",scope:"Author in-memory public-field projection and planned cardinality only; no context-lab check, prompt renderer, execution, selected profiles or actual outputs",sources,common:{scoreDefinitions:Object.keys(keys[0].key.scoring).length,rules:keys[0].key.rules.length,questionIds:ids},readings:fields.map(({instructions,task,judgeInstructions,properties,...rest})=>rest),planned:{families:"Three symbolic positions, not selected models",cells:cells.length,outcomes:outcomes.length,voteSlots:slots.length},fidelity:"All 16 per-question JSON key strings decode to their complete retained entries; common scoring/rules and reader instructions/task are equal on both sides; no source key field omitted."},null,2));'

localChecks.command:
node --input-type=module -e '
import fs from "node:fs";
import path from "node:path";
import assert from "node:assert/strict";
const files=["docs/reviews/browser-peer-scale-assurance/browser-scale-public-binding.md","docs/BOARD.md","docs/VERIFICATION.md"];
const slug=s=>s.trim().toLowerCase().replace(/[`*_~]/gu,"").replace(/[.,:;!?()[\]{}'\''"\\/|<>@#$%^&+=]/gu,"").replace(/\s/gu,"-");
const broken=[];let count=0;
for(const file of files){
 const body=fs.readFileSync(file,"utf8");
 for(const m of body.matchAll(/\]\(([^)\s]*)\)/gu)){
  const ref=m[1];if(/^[a-z][a-z\d+.-]*:/iu.test(ref))continue;
  const [relative,anchor]=ref.split("#");
  const target=relative?path.resolve(path.dirname(file),relative):path.resolve(file);
  count++;
  if(!fs.existsSync(target)){broken.push({file,ref,reason:"missing target"});continue;}
  if(anchor&&target.endsWith(".md")){
   const headings=new Set([...fs.readFileSync(target,"utf8").matchAll(/^#{1,6}\s+(.+?)\s*$/gmu)].map(m=>slug(m[1])));
   if(!headings.has(anchor))broken.push({file,ref,reason:"missing heading"});
  }
 }
}
assert.ok(count>50,"empty or incomplete link population");
assert.deepEqual(broken,[]);
console.log(JSON.stringify({result:"PASS",files,localReferences:count,broken}));
'

scopePreservation.command:
node --input-type=module -e 'import fs from "node:fs";import cp from "node:child_process";import path from "node:path";import crypto from "node:crypto";import assert from "node:assert/strict";
const recordPath="docs/reviews/browser-peer-scale-assurance/browser-scale-public-binding-checks.json";
const r=JSON.parse(fs.readFileSync(recordPath,"utf8"));const agp="/home/apnex/taceng/agp";
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");const git=(cwd,...a)=>cp.execFileSync("git",a,{cwd,encoding:"utf8"});
const tracking=new Set(r.trackingChanges.map(e=>e[0]));const repositories=[];
for(const [cwd,b] of Object.entries(r.baseline.data).filter(([k])=>k.startsWith("/"))){
 assert.equal(git(cwd,"rev-parse","HEAD").trim(),b.head);assert.equal(git(cwd,"rev-parse","refs/remotes/origin/main").trim(),b.origin);assert.equal(git(cwd,"diff","--cached","--binary"),b.index);
 const dirty=git(cwd,"ls-files","--modified","--others","--exclude-standard","-z").split("\0").filter(Boolean);
 const expected=cwd===agp?[...b.dirty,...r.allowedNewFiles]:b.dirty;assert.deepEqual([...dirty].sort(),[...expected].sort());
 if(cwd!==agp)assert.equal(git(cwd,"status","--porcelain=v1","--untracked-files=all"),b.status);
 let count=0;for(const [p,h] of Object.entries(b.files)){if(cwd===agp&&tracking.has(p))continue;assert.equal(sha(fs.readFileSync(path.join(cwd,p))),h,p+" changed");count++;}
 repositories.push({path:cwd,head:b.head,localOrigin:b.origin,indexEmpty:b.index==="",dirtyPaths:dirty.length,comparedUnchangedFiles:count});
}
for(const p of tracking){let text=fs.readFileSync(p,"utf8");for(const [file,before,after]of r.trackingChanges.filter(e=>e[0]===p)){assert.equal(text.split(after).length-1,1);text=text.replace(after,before);}
 if(p==="docs/VERIFICATION.md"){assert.equal(text.split(r.addedVerificationSection).length-1,1);text=text.replace(r.addedVerificationSection,"");}
 assert.equal(sha(Buffer.from(text)),r.baseline.data[agp].files[p],p+" inverse content mismatch");
}
const packet=git(agp,"ls-files","docs/reviews/browser-peer-scale-assurance","-z").split("\0").filter(Boolean);assert.equal(packet.length,20);
for(const p of [...packet,"VISION.md","docs/DECISIONS.md"])assert.equal(sha(fs.readFileSync(p)),sha(cp.execFileSync("git",["show",r.provenance.agp+":"+p],{cwd:agp})),p+" differs from frozen revision");
const projection=JSON.parse(r.fieldProjection.output);for(const source of projection.sources)assert.equal(sha(fs.readFileSync(source.path)),source.sha256,source.path+" changed");
const artifacts=[r.allowedNewFiles[0],"docs/BOARD.md","docs/VERIFICATION.md"].map(p=>{const b=fs.readFileSync(p);return{path:p,bytes:b.length,sha256:sha(b)}});
console.log(JSON.stringify({result:"PASS",repositories,committedPacketFilesPreserved:20,otherPreExistingDirtyFilesPreserved:r.baseline.data[agp].dirty.length-tracking.size,sourceIdentitiesPreserved:projection.sources.length,exactBoardEntriesChanged:4,exactCurrentFindingRowsChanged:1,verificationHistoryPreserved:true,previousReviewAndReadinessRecordsPreserved:true,artifacts,meaning:"Author file-byte and Git-state preservation; not semantic or execution assurance."},null,2));'

